import numpy as np, pandas as pd, matplotlib.pyplot as plt
def load_ca(fn,chain='A'):
    d={}
    for L in open(fn):
        if L.startswith('ATOM') and L[21]==chain and L[12:16].strip()=='CA':
            d[int(L[22:26])]=np.array([float(L[30:38]),float(L[38:46]),float(L[46:54])])
    return d
def helices(fn,chain='A'):
    H=[]
    for L in open(fn):
        if L.startswith('HELIX') and L[19]==chain: H.append((int(L[21:25]),int(L[33:37])))
    # merge overlapping/adjacent
    H.sort(); out=[]
    for a,b in H:
        if out and a<=out[-1][1]+1: out[-1]=(out[-1][0],max(out[-1][1],b))
        else: out.append((a,b))
    return out
def membrane_axis(ca):
    X=np.array(list(ca.values())); X=X-X.mean(0)
    w,v=np.linalg.eigh(X.T@X)
    return v[:,np.argmax(w)], np.array(list(ca.values())).mean(0)

rows=[]
for fn,label in [('1OKC.pdb','AAC1 bovine (1OKC)'),('12OY.pdb','MTCH2 human (12OY)')]:
    ca=load_ca(fn); ax,c=membrane_axis(ca)
    for a,b in helices(fn):
        pts=np.array([ca[r] for r in range(a,b+1) if r in ca])
        if len(pts)<5: continue
        proj=(pts-c)@ax
        rows.append({'structure':label,'helix':f'{a}-{b}','n_res':len(pts),
                     'span_along_axis_A':round(float(proj.max()-proj.min()),1),
                     'mid_z':round(float(proj.mean()),1),
                     'TM_like': (proj.max()-proj.min())>24})
H=pd.DataFrame(rows)
print(H.to_string(index=False))
print()
print(H.groupby('structure').TM_like.sum())
H.to_csv('helix_topology_1OKC_vs_12OY.csv',index=False)

fig,axes=plt.subplots(1,2,figsize=(11,5),sharey=True)
for axx,(lab,g) in zip(axes,H.groupby('structure')):
    y=np.arange(len(g))
    axx.barh(y,g.span_along_axis_A,color=['#2a7f62' if t else '#b0b0b0' for t in g.TM_like])
    axx.set_yticks(y); axx.set_yticklabels(g.helix,fontsize=8)
    axx.axvline(24,ls='--',c='k',lw=1)
    axx.set_title(f'{lab}\nTM-like helices (span > 24 A): {int(g.TM_like.sum())}',fontsize=10)
    axx.set_xlabel('helix span along membrane normal (A)')
plt.tight_layout(); plt.show()
